ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg226:
;## ntc_lmul ntc_ldata
; ntc_la * ntc_lb -> ntc_lr (low 32 bits, same signed / unsigned). jp (ix)
ntc_lmul:
			ld hl, 0
			ld (ntc_lr), hl
			ld (ntc_lr+2), hl
			ld b, 32
ntc_lm_loop:
			ld hl, ntc_lb+3
			srl (hl)
			dec hl
			rr (hl)
			dec hl
			rr (hl)
			dec hl
			rr (hl)
			jr nc, ntc_lm_skip
			ld de, ntc_la
			ld hl, ntc_lr
			ld a, (de)
			add a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
ntc_lm_skip:
			ld hl, ntc_la
			sla (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			djnz ntc_lm_loop
			jp (ix)

ntc_rg226_e:
			IF ($ < 65536) && (ntc_rg227_e - ntc_rg227 + $ > 47616)	; fwdref-ok
